# Spec 195: final bulk validation figures, built end to end on ONE cohort: the 6 CROP-seq KOs TEAD4, TWIST1, PITX1, SOX9, TEAD2, BPTF + non-targeting controls,
# cell lines MSTO-211H, NCI-H2452, NCI-H28 (8 NTC + 35 KO samples). TCF3, HMGA1, RUNX1/2, SNAI2, NCI-H2052 and every other sample are removed before any computation.
#
#   processing (all on the cohort only)
#     bulk     gene counts -> per line filterByExpr (genes kept in all 3 lines) -> TMM log-CPM (edgeR) -> cell-cycle score S.Score + G2M.Score (Seurat, on TMM log-CPM)
#              -> regressed out over the line's samples (cc) -> KO profiles = mean of the 6 KO means - KO mean; module scores (AddModuleScore, top-50 Cm genes) on the regressed values
#     screen   NCI-H2052 CROP-seq cells with a unique guide of NTC or the 6 KOs -> Seurat CellCycleScoring on these cells -> genes detected in >= 1% of them
#              -> S/G2M regressed out of the KO means -> KO profiles as in bulk; vst variable genes on these cells; module scores and their cell-cycle regression on these cells
#     per-sample annotations that do not depend on the other samples are read from earlier tables: genotype line and corrected KO label (spec128 SA), indel % and
#     guide reads per sample (spec121, spec155a, spec156; read pile-ups and guide counts from each BAM)
#
#   pages (one PDF, final6KO_all.pdf; every page also saved as png and pdf)
#     1  summary (as fig85_summary_TMM_noTCF3_HMGA1_noH2052): A replicates  B KO target rings  C proliferation (TMM; KO = median over lines of the replicate means,
#        one-sided rank-sum vs the NTC scores)  D match to the screen  E-G Cm20-TEAD4, Cm8-TWIST1, Cm1-TEAD2 (screen cells as violins)
#     cell-line colours: MSTO-211H #1BAF7A, NCI-H2452 #E87BA4, NCI-H28 #B5AE67
#     2  per line match to the screen (as fig58 panel A, all samples): per KO the same-KO correlation in each line vs the other-KO correlations; KOs ordered by median, no pooled group
#     3  proliferation per KO: the samples of each KO vs the NTC samples (TMM scores of page 1 C), one-sided rank-sum per KO; KOs ordered by median
#     4  sample identity (as fig66): guide reads of the 6 target genes and of the non-targeting guides found in the controls (square cells)
#     5  read coverage: reads assigned to genes per sample
#     NORM=tpm reruns every bulk panel on log2(TPM + 1) (A: genes with mean TPM >= 1); outputs tagged _TPM
#     6  cell-line identity (as CNA_correlation_heatmap_used_samples): expression-based copy-number profile (10 Mb windows) of each sample vs CCLE
# needs: STAR counts (load_bulk_S91), screen object (load_screen), scRNA_PM_modules.rds, spec72_profiles_S70.rds (sample list), spec128_inputs.rds (SA annotation only),
#        spec121_indel_matrix.csv, spec121_guide_reads_matrix.csv, spec155a_NTC_guide_reads.csv, spec156_NTC_indel_per_sample.csv, CCLE RNA-seq (RSEM TPM), GENCODE v46 GTF
# outputs ($CROP_OUT): final6KO_p1_summary, final6KO_p2_per_line_match, final6KO_p3_proliferation_per_KO, final6KO_p4_sample_identity, final6KO_p5_CNA_vs_CCLE (.png/.pdf),
#        final6KO_all.pdf, final6KO_stats.csv
here <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)[1])))
source(file.path(here, "repro_common.R")); source(file.path(here, "spec_common.R")); source(file.path(here, "profiles.R")); source(file.path(here, "agree_common.R"))
suppressPackageStartupMessages({ library(Seurat); library(limma); library(edgeR); library(data.table) }); options(Seurat.object.assay.version = "v3", width = 200); set.seed(5)

KOS <- c("TEAD4", "TWIST1", "PITX1", "SOX9", "TEAD2", "BPTF"); GR <- c("NTC", KOS); LN <- c("MSTO-211H", "NCI-H2452", "NCI-H28"); LC <- c(`MSTO-211H` = "#1BAF7A", `NCI-H2452` = "#E87BA4", `NCI-H28` = "#B5AE67")
SH <- function(l) sub("NCI-|-211H", "", l); kcol <- function(k) ifelse(k %in% names(KO_COL), KO_COL[k], "grey30"); fp <- function(p) ifelse(is.na(p), "n/a", ifelse(p < 0.001, formatC(p, format = "e", digits = 0), formatC(p, format = "g", digits = 2)))
PAIRS <- list(c(Cm = "Cm20", KO = "TEAD4"), c(Cm = "Cm8", KO = "TWIST1"), c(Cm = "Cm1", KO = "TEAD2")); MINEXP <- 0.1; TOPN <- 500
NORM <- Sys.getenv("NORM", "tmm"); NTAG <- if (NORM == "tpm") "_TPM" else ""; NLAB <- if (NORM == "tpm") "log2(TPM + 1)" else "TMM log-CPM"   # NORM=tpm: every bulk panel on log2(TPM + 1) (gene lengths of spec177) instead of TMM log-CPM; outputs tagged _TPM
AFLAB <- if (NORM == "tpm") "Mean TPM >= 1" else "Mean CP10K >= 0.1"
GTF <- "/sc/arion/projects/Tsankov_Normal_Lung/genome_assemblies/human/gencode.v46.annotation.gtf"; CRDS <- "/sc/arion/projects/Tsankov_Normal_Lung/Bruno/Public_data/CCLE/CCLE_RNAseq_rsem_genes_tpm.rds"

## =============================================================== 1. samples and counts (cohort only)
SA <- readRDS(file.path(OUT, "spec128_inputs.rds"))$SA; SA <- SA[SA$line %in% LN & SA$KO %in% GR, c("sample", "line", "KO", "indel_best")]; SA <- SA[order(match(SA$line, LN), match(SA$KO, GR), SA$sample), ]; rownames(SA) <- SA$sample
stopifnot(nrow(SA) == 43, all(table(SA$KO)[KOS] > 0)); cat("cohort:", nrow(SA), "samples\n"); print(table(factor(SA$KO, GR), factor(SA$line, LN)))
pr <- readRDS(file.path(OUT, sprintf("spec72_profiles_S70%s.rds", DSUF))); CS <- load_bulk_S91(pr$samples, drop_bad_ntc = TRUE, drop_kos = "RUNX1")$cs[, SA$sample]; CS <- CS[rowSums(CS) > 0, ]
SA$label <- paste0(SH(SA$line), "_", sub("^[^_]+_", "", SA$sample)); SA$relabelled <- sub("_.*", "", SA$sample) != SH(SA$line)
lines_of <- function(cl, set = GR) SA$sample[SA$line == cl & SA$KO %in% set]

## =============================================================== 2. bulk processing
reg <- function(y, X) { X <- scale(as.matrix(X), scale = FALSE); X <- X[, apply(X, 2, sd) > 0, drop = FALSE]; y - y %*% X %*% solve(crossprod(X)) %*% t(X) }
ccs <- function(y) { y <- y - min(y); rownames(y) <- gsub("_", "-", rownames(y)); o <- CreateSeuratObject(counts = round(y)); o <- suppressWarnings(SetAssayData(o, layer = "data", new.data = y))
  o <- suppressWarnings(CellCycleScoring(o, s.features = intersect(Seurat::cc.genes$s.genes, rownames(y)), g2m.features = intersect(Seurat::cc.genes$g2m.genes, rownames(y)), set.ident = FALSE)); setNames(as.numeric(o$S.Score + o$G2M.Score), colnames(y)) }
ms <- function(y, sets) { y <- y - min(y); sb <- suppressWarnings(SetAssayData(CreateSeuratObject(counts = round(pmax(y, 0))), layer = "data", new.data = y)); sb <- suppressWarnings(AddModuleScore(sb, features = sets, name = "Cm_", seed = 1))
  x <- t(as.matrix(sb@meta.data[colnames(y), paste0("Cm_", seq_along(sets))])); rownames(x) <- names(sets); x }
keep <- Reduce(intersect, lapply(LN, function(cl) { s <- lines_of(cl); rownames(CS)[filterByExpr(DGEList(CS[, s]), group = SA[s, "KO"])] })); cat("bulk genes (filterByExpr in every line):", length(keep), "\n")
top50 <- cm_top50(); CM <- names(top50); TMM <- list(); TMMcc <- list(); MODb <- list()
if (NORM == "tpm") { GL <- read.csv(file.path(OUT, "spec177_gene_lengths.csv")); LEN <- setNames(GL$length_bp / 1e3, GL$gene); stopifnot(all(rownames(CS) %in% names(LEN))) }
tpm <- function(s) { r <- CS[, s] / LEN[rownames(CS)]; t(t(r) / colSums(r)) * 1e6 }
for (cl in LN) { s <- lines_of(cl); y <- if (NORM == "tpm") log2(tpm(s)[keep, ] + 1) else normalise(CS[keep, s], "tmm")$y; SA[s, "cc"] <- ccs(y)[s]; TMM[[cl]] <- y; TMMcc[[cl]] <- reg(y, SA[s, "cc", drop = FALSE]); MODb[[cl]] <- ms(TMMcc[[cl]], top50) }
kprof <- function(y, s) { gm <- sapply(KOS, function(k) rowMeans(y[, s[SA[s, "KO"] == k], drop = FALSE])); rowMeans(gm) - gm }   # mean of the KO means - KO (positive = lower in the KO)

## =============================================================== 3. screen processing (cohort cells only)
srt <- load_screen(); grp <- as.character(srt$merged_call); srt <- srt[, grp %in% GR]; srt <- srt[Matrix::rowSums(GetAssayData(srt, layer = "counts") > 0) > 0, ]; g <- as.character(srt$merged_call);   # genes with no read in these cells removed (Seurat scoring bins genes by mean expression)
 cat("screen cells:\n"); print(table(factor(g, GR)))
srt <- suppressWarnings(CellCycleScoring(srt, s.features = Seurat::cc.genes$s.genes, g2m.features = Seurat::cc.genes$g2m.genes, set.ident = FALSE))
Y <- GetAssayData(srt, layer = "data"); Y <- Y[Matrix::rowSums(Y > 0) >= 0.01 * ncol(Y), ]; Gs <- intersect(keep, rownames(Y)); Y <- Y[Gs, ]
Xc <- scale(cbind(srt$S.Score, srt$G2M.Score), scale = FALSE); Bc <- as.matrix(Y %*% Xc) %*% solve(crossprod(Xc)); gm <- sapply(GR, function(k) Matrix::rowMeans(Y[, g == k, drop = FALSE])); gx <- sapply(GR, function(k) colMeans(Xc[g == k, , drop = FALSE]))
SCR <- gm - Bc %*% gx; Sp <- rowMeans(SCR[, KOS]) - SCR[, KOS]; hv <- intersect(VariableFeatures(FindVariableFeatures(srt, selection.method = "vst", nfeatures = nrow(srt), verbose = FALSE)), Gs)
o <- suppressWarnings(AddModuleScore(srt, features = top50, name = "Cm_", seed = 1)); s50 <- as.matrix(o@meta.data[, paste0("Cm_", seq_along(CM))]); colnames(s50) <- CM; s50 <- apply(s50, 2, function(v) resid(lm(v ~ Xc)) + mean(v))
Ss <- scale(s50); kc <- g %in% KOS; Ss <- Ss[kc, ]; gs <- g[kc]; sp <- sapply(KOS, function(k) sapply(CM, function(m) wilcox.test(Ss[gs == k, m], Ss[gs != k, m])$p.value)); sfdr <- matrix(p.adjust(sp, "BH"), nrow(sp), dimnames = dimnames(sp))

## =============================================================== 4. analyses
perms <- function(v) if (length(v) <= 1) list(v) else do.call(c, lapply(seq_along(v), function(i) lapply(perms(v[-i]), function(r) c(v[i], r)))); PM <- do.call(rbind, perms(seq_along(KOS)))
## A  replicate structure: TMM log-CPM, no regression, genes with mean CP10K >= 0.1 over the line's KO samples, centred on those samples, Spearman
auc <- function(w, o) { r <- rank(c(w, o)); (sum(r[seq_along(w)]) - length(w) * (length(w) + 1) / 2) / (length(w) * length(o)) }
P13 <- do.call(rbind, lapply(LN, function(cl) { s <- lines_of(cl, KOS); cp <- if (NORM == "tpm") tpm(s) else t(t(CS[, s]) / colSums(CS[, s])) * 1e4; y <- TMM[[cl]][, s]; y <- y[rownames(y) %in% rownames(cp)[rowMeans(cp) >= (if (NORM == "tpm") 1 else MINEXP)], ]; C <- cor(y - rowMeans(y), method = "spearman"); i <- which(upper.tri(C), arr.ind = TRUE)
  data.frame(line = cl, n_genes = nrow(y), r = C[i], same = SA[s[i[, 1]], "KO"] == SA[s[i[, 2]], "KO"]) }))
S13 <- do.call(rbind, lapply(LN, function(cl) { x <- P13[P13$line == cl, ]; data.frame(line = cl, n_genes = x$n_genes[1], AUC = auc(x$r[x$same], x$r[!x$same]), p = wilcox.test(x$r[x$same], x$r[!x$same], alternative = "greater")$p.value) }))
## B  KO target genes: TMM log-CPM, group medians, z per gene over the groups, then z per KO row over the targets, per line
rz <- function(M) { Z <- (M - rowMeans(M, na.rm = TRUE)) / matrixStats::rowSds(M, na.rm = TRUE); Z[!is.finite(Z)] <- NA; Z }
KL <- lapply(setNames(LN, LN), function(cl) { y <- TMM[[cl]]; M <- t(sapply(KOS, function(gn) sapply(GR, function(k) { s <- lines_of(cl, k); if (!length(s) || !gn %in% rownames(y)) NA else median(y[gn, s]) }))); rz(t(rz(M)[KOS, GR])) })
RK <- sapply(LN, function(cl) sapply(KOS, function(k) rank(KL[[cl]][k, ], na.last = "keep")[k]))
## C  proliferation, TMM: per line (cc - mean NTC) / SD; KO = median over lines of the replicate means; one-sided rank-sum vs the NTC scores
SA$z <- NA; for (cl in LN) { s <- lines_of(cl); SA[s, "z"] <- (SA[s, "cc"] - mean(SA[s[SA[s, "KO"] == "NTC"], "cc"])) / sd(SA[s, "cc"]) }
ntc <- SA[SA$KO == "NTC", ]; klp <- aggregate(z ~ KO + line, SA[SA$KO != "NTC", ], mean); pmC <- sapply(KOS, function(k) median(klp$z[klp$KO == k])); pC <- suppressWarnings(wilcox.test(pmC, ntc$z, alternative = "less")$p.value)
## D  match to the screen: lines pooled; genes = top 500 screen x top 500 bulk variable
vg <- Gs[order(-rowMeans(sapply(LN, function(cl) matrixStats::rowVars(TMMcc[[cl]][Gs, ]))))]; f <- intersect(hv[1:TOPN], vg[1:TOPN]); BL <- lapply(setNames(LN, LN), function(cl) kprof(TMMcc[[cl]][Gs, ], lines_of(cl, KOS))); PB <- Reduce(`+`, BL) / length(BL)
CD <- cor(Sp[f, ], PB[f, ], method = "spearman"); dimnames(CD) <- list(KOS, KOS); same <- diag(CD); other <- CD[row(CD) != col(CD)]; pD <- wilcox.test(same, other, alternative = "greater")$p.value
nul <- rowMeans(matrix(CD[cbind(as.vector(col(PM)), as.vector(PM))], nrow(PM))); pDperm <- mean(nul >= mean(same) - 1e-12)
## E-G  modules: bulk z within line over the KO samples, replicates averaged; screen z over NTC + KO cells
B0 <- do.call(rbind, lapply(LN, function(cl) { s <- lines_of(cl, KOS); M <- MODb[[cl]][, s, drop = FALSE]; z <- t((M - rowMeans(M)) / matrixStats::rowSds(M)); data.frame(line = cl, KO = SA[s, "KO"], z, check.names = FALSE) })); B0 <- aggregate(B0[, CM], list(line = B0$line, KO = B0$KO), mean)
## page 2: per line correlations
CL <- lapply(setNames(LN, LN), function(cl) { C <- cor(Sp[f, ], BL[[cl]][f, ], method = "spearman"); dimnames(C) <- list(KOS, KOS); C }); SMk <- lapply(setNames(KOS, KOS), function(k) sapply(LN, function(cl) CL[[cl]][k, k])); OTk <- lapply(setNames(KOS, KOS), function(k) unlist(lapply(LN, function(cl) CL[[cl]][k, setdiff(KOS, k)])))
T58 <- do.call(rbind, lapply(KOS, function(k) data.frame(KO = k, same_mean = mean(SMk[[k]]), same_pooled = same[k], other_median = median(OTk[[k]]), wilcox_p = wilcox.test(SMk[[k]], OTk[[k]], alternative = "greater")$p.value))); T58$fdr <- p.adjust(T58$wilcox_p, "BH")
allS <- unlist(SMk); allO <- unlist(OTk); p58 <- wilcox.test(allS, allO, alternative = "greater")$p.value
## page 3: proliferation per KO (TMM scores of page 1 C): KO samples vs NTC samples, one-sided rank-sum, BH over the KOs
TP <- do.call(rbind, lapply(KOS, function(k) { v <- SA$z[SA$KO == k]; data.frame(KO = k, n = length(v), median = median(v), wilcox_p = suppressWarnings(wilcox.test(v, ntc$z, alternative = "less")$p.value)) })); TP$fdr <- p.adjust(TP$wilcox_p, "BH"); TP <- TP[order(-TP$median), ]
## page 3b: as page 3 with the replicates of each KO averaged per line (one value per KO x line, klp of panel C) vs the NTC samples (NTC line means are 0 by construction)
TPm <- do.call(rbind, lapply(KOS, function(k) { v <- klp$z[klp$KO == k]; data.frame(KO = k, n = length(v), median = median(v), wilcox_p = suppressWarnings(wilcox.test(v, ntc$z, alternative = "less")$p.value)) })); TPm$fdr <- p.adjust(TPm$wilcox_p, "BH"); TPm <- TPm[order(-TPm$median), ]
## page 5: copy-number proxy vs CCLE
REF <- c("NCI-H2052", "MSTO-211H", "NCI-H2452", "NCI-H28"); CCN <- setNames(c("NCIH2052_PLEURA", "MSTO211H_PLEURA", "NCIH2452_PLEURA", "NCIH28_PLEURA"), REF); CHR <- paste0("chr", c(1:22, "X"))
gt <- fread(cmd = sprintf("awk -F'\\t' '$3==\"gene\"' %s", shQuote(GTF)), header = FALSE, sep = "\t", select = c(1, 4, 9)); gt <- data.frame(chr = gt$V1, start = gt$V4, name = sub('.*gene_name "([^"]+)".*', "\\1", gt$V9), type = sub('.*gene_type "([^"]+)".*', "\\1", gt$V9))
gt <- gt[gt$chr %in% CHR & gt$type %in% c("protein_coding", "lncRNA") & !duplicated(gt$name), ]; rownames(gt) <- gt$name; lb <- log2(t(t(CS) / colSums(CS)) * 1e6 + 1); lc <- log2(as.matrix(readRDS(CRDS)[, CCN]) + 1); colnames(lc) <- REF
GC <- Reduce(intersect, list(rownames(gt), rownames(lb), rownames(lc))); GC <- GC[rowMeans(lb[GC, ]) >= 1 & rowMeans(lc[GC, ]) >= 1]; gw <- split(GC, paste(gt[GC, "chr"], floor(gt[GC, "start"] / 1e7), sep = ":")); gw <- gw[lengths(gw) >= 5]
wprof <- function(M) scale(t(sapply(gw, function(x) colMeans(M[x, , drop = FALSE])))); RC <- cor(wprof(lb[GC, ]), wprof(lc[GC, ])); SA$best_CCLE <- REF[apply(RC[SA$sample, ], 1, which.max)]
## page 4: guide reads and indels
IN <- as.matrix(read.csv(file.path(OUT, "spec121_indel_matrix.csv"), row.names = 1, check.names = FALSE))[KOS, SA$sample]; GU <- as.matrix(read.csv(file.path(OUT, "spec121_guide_reads_matrix.csv"), row.names = 1, check.names = FALSE))[KOS, SA$sample]
NT <- read.csv(file.path(OUT, "spec155a_NTC_guide_reads.csv")); ntc_rpm <- tapply(NT$rpm[grepl("found", NT$guide)], NT$sample[grepl("found", NT$guide)], sum)[SA$sample]; NI <- read.csv(file.path(OUT, "spec156_NTC_indel_per_sample.csv")); NI <- NI[NI$set == "found", ]; ntc_ind <- setNames(ifelse(NI$n_cover >= 10, NI$indel_pct, NA), NI$sample)[SA$sample]
GUx <- rbind(GU, `NTC (found)` = ntc_rpm); INx <- rbind(IN, `NTC (found)` = ntc_ind)

## =============================================================== 5. statistics table
ST <- rbind(data.frame(page = 1, panel = "A", test = sprintf("%s: same-KO vs different-KO pairs, AUC %.2f, %d genes", S13$line, S13$AUC, S13$n_genes), p = S13$p),
  data.frame(page = 1, panel = "B", test = sprintf("own target most reduced in %d of %d KO x line", sum(RK == 1, na.rm = TRUE), sum(!is.na(RK))), p = NA),
  data.frame(page = 1, panel = "C", test = sprintf("proliferation: %d of %d KOs below NTC (median over lines), rank-sum vs %d NTC scores", sum(pmC < 0), length(pmC), nrow(ntc)), p = pC),
  data.frame(page = 1, panel = "D", test = sprintf("match to screen: same %.3f vs other %.3f, %d genes; permutation p %.3g", mean(same), mean(other), length(f), pDperm), p = pD),
  do.call(rbind, lapply(PAIRS, function(x) { m <- x[["Cm"]]; k <- x[["KO"]]; data.frame(page = 1, panel = "E-G", test = sprintf("%s in %s: screen FDR %.2g; bulk lower by %.2f", m, k, sfdr[m, k], mean(B0[B0$KO != k, m]) - mean(B0[B0$KO == k, m])), p = suppressWarnings(wilcox.test(B0[B0$KO == k, m], B0[B0$KO != k, m])$p.value)) })),
  data.frame(page = 2, panel = T58$KO, test = sprintf("per line same-KO mean %.2f vs other-KO median %.2f (FDR %.2g)", T58$same_mean, T58$other_median, T58$fdr), p = T58$wilcox_p),
  data.frame(page = 3, panel = TP$KO, test = sprintf("proliferation, %d KO samples vs %d NTC samples, median %.2f (FDR %.2g)", TP$n, nrow(ntc), TP$median, TP$fdr), p = TP$wilcox_p),
  data.frame(page = "3b", panel = TPm$KO, test = sprintf("proliferation, %d line means (replicates averaged) vs %d NTC samples, median %.2f (FDR %.2g)", TPm$n, nrow(ntc), TPm$median, TPm$fdr), p = TPm$wilcox_p),
  data.frame(page = 4, panel = "reads", test = sprintf("reads assigned to genes per sample: median %.1f M (range %.1f-%.1f)", median(colSums(CS)) / 1e6, min(colSums(CS)) / 1e6, max(colSums(CS)) / 1e6), p = NA),
  data.frame(page = 5, panel = "CNA", test = sprintf("best CCLE match = genotype line for %d of %d samples (%d genes, %d windows)", sum(SA$best_CCLE == SA$line), nrow(SA), length(GC), length(gw)), p = NA))
write.csv(ST, file.path(OUT, paste0("final6KO", NTAG, "_stats.csv")), row.names = FALSE); print(ST, row.names = FALSE, right = FALSE)

## =============================================================== 6. drawing helpers (fig74 / fig85 graphics, fig13c line colours)
U <- 0.56; BW <- 0.72; MAI <- c(0.95, 0.66, 0.85, 0.06); XA <- c(0.4, 3.45); XC <- c(0.4, 6.15); wA <- MAI[2] + MAI[4] + diff(XA) * U; wC <- MAI[2] + MAI[4] + diff(XC) * U; HP <- 4.5; CX <- 0.95
spread <- function(y, gap) { o <- order(y); v <- y[o]; for (i in seq_along(v)[-1]) if (v[i] - v[i - 1] < gap) v[i] <- v[i - 1] + gap; v <- v - (mean(v) - mean(y[o])); y[o] <- v; y }
frame <- function(xl, yl, ylab) { par(mai = MAI, mgp = c(2.3, 0.6, 0), tcl = -0.3); plot(NA, xlim = xl, ylim = yl, xaxs = "i", xaxt = "n", bty = "n", las = 1, cex.axis = CX, cex.lab = CX * 1.05, xlab = "", ylab = ylab); abline(h = 0, col = "#b2182b", lwd = 1.5) }
bx <- function(v, at, col) boxplot(v, at = at, add = TRUE, col = adjustcolor(col, 0.32), border = INK2, outline = FALSE, axes = FALSE, boxwex = BW, lwd = 0.8)
greypts <- function(v, at) { set.seed(1); points(jitter(rep(at, length(v)), amount = 0.16), v, pch = 21, bg = adjustcolor("grey35", 0.55), col = NA, cex = 0.8) }
linepts <- function(v, lines, at, lab = FALSE, yl) { xo <- if (lab) rep(at, length(v)) else at + seq(-0.2, 0.2, length.out = length(LN))[match(lines, LN)]; points(xo, v, pch = 21, bg = LC[lines], col = "black", cex = 1.5, lwd = 0.7); if (lab) { ly <- spread(v, diff(yl) * 0.05); segments(at + 0.13, v, at + 0.33, ly, col = MUTED, lwd = 0.5); text(at + 0.36, ly, SH(lines), adj = 0, cex = CX * 0.85, col = LC[lines], font = 2, xpd = NA) } }
kodia <- function(v, nm, at, yl) { points(rep(at, length(v)), v, pch = 23, bg = kcol(nm), col = "black", cex = 1.6, lwd = 0.7); ly <- spread(v, diff(yl) * 0.052); segments(at + 0.13, v, at + 0.38, ly, col = MUTED, lwd = 0.5); text(at + 0.41, ly, nm, adj = 0, cex = CX * 0.85, col = kcol(nm), font = 2, xpd = NA) }
brk <- function(x1, x2, yl, lab, bold) { yb <- yl[2] - diff(yl) * 0.1; h <- diff(yl) * 0.015; segments(c(x1, x1, x2), c(yb, yb - h, yb - h), c(x2, x1, x2), c(yb, yb, yb), lwd = 0.7); text((x1 + x2) / 2, yb, lab, pos = 3, cex = CX, font = if (bold) 2 else 1) }
ttl <- function(a, b, c_, col = "black") { mtext(a, side = 3, adj = 0, line = 2.9, font = 2, cex = CX * 0.82, col = col); mtext(b, side = 3, adj = 0, line = 1.75, cex = CX * 0.62, col = INK2); mtext(c_, side = 3, adj = 0, line = 0.7, cex = CX * 0.62, col = INK2) }
xlab2 <- function(at, lab) axis(1, at = at, labels = lab, tick = FALSE, cex.axis = CX * 0.95, font = 2, padj = 0.5, line = -0.5)
vio <- function(v, at, col, w = 0.38) { lim <- quantile(v, c(0.005, 0.995)); d <- density(v, n = 256, from = lim[1], to = lim[2]); h <- d$y / max(d$y) * w; polygon(c(at - h, rev(at + h)), c(d$x, rev(d$x)), col = adjustcolor(col, 0.38), border = INK2, lwd = 0.6); q <- quantile(v, c(0.25, 0.5, 0.75)); segments(at, q[1], at, q[3], lwd = 2.4, col = INK2); points(at, q[2], pch = 21, bg = "white", col = INK2, cex = 0.95, lwd = 0.8) }
stars <- function(p) ifelse(p < 0.001, "***", ifelse(p < 0.01, "**", ifelse(p < 0.05, "*", "ns")))
p_prolif <- function(zn, zk, nm, p, title, sub, testlab) { yl <- range(c(zn$z, zk)) + c(-0.3, 0.62); frame(XA, yl, "proliferation score, SD from NTC"); rect(par("usr")[1], par("usr")[3], par("usr")[2], 0, col = adjustcolor("#2166ac", 0.05), border = NA); abline(h = 0, col = "#b2182b", lwd = 1.5)
  bx(zn$z, 1, "#7a7a7a"); linepts(zn$z, zn$line, 1); bx(zk, 2, "#eb6834"); kodia(zk, nm, 2, yl); xlab2(1:2, c("NTC\nsamples", "KOs")); brk(1, 2, yl, sprintf("p = %s", fp(p)), p < 0.05); ttl(title, sprintf("%d of %d KOs below NTC; median %.2f SD", sum(zk < 0), length(zk), median(zk)), testlab) }
p_match <- function(title = "D  Match to the CROP-seq screen") { yl <- range(c(same, other)) + c(-0.06, 0.14); frame(XA, yl, "correlation, screen KO vs bulk KO"); bx(other, 1, "#7a7a7a"); greypts(other, 1); bx(same, 2, "#eb6834"); kodia(same, KOS, 2, yl); xlab2(1:2, c("other\nKOs", "same\nKO")); brk(1, 2, yl, sprintf("p = %s", fp(pD)), pD < 0.05)
  ttl(title, sprintf("same %.2f vs other %.2f", mean(same), mean(other)), sprintf("n = %d same vs %d other; perm. p %s", length(same), length(other), fp(pDperm))) }
p_cm <- function(x, letter) { m <- x[["Cm"]]; k <- x[["KO"]]; a <- Ss[gs == k, m]; o <- Ss[gs != k, m]; ba <- B0[B0$KO == k, ]; bo <- B0[B0$KO != k, ]; pl <- sapply(LN, function(cl) { v <- ba[ba$line == cl, m]; if (length(v)) v - mean(bo[bo$line == cl, m]) else NA }); ds <- mean(a) - mean(o); pb <- suppressWarnings(wilcox.test(ba[[m]], bo[[m]])$p.value)
  yl <- range(c(quantile(c(a, o), c(0.005, 0.995)), B0[[m]])) + c(-0.3, 0.95); frame(XC, yl, sprintf("%s module score (z)", m)); abline(v = 2.9, col = GRID); vio(o, 1, "#7a7a7a"); vio(a, 2, kcol(k)); bx(bo[[m]], 3.8, "#7a7a7a"); greypts(bo[[m]], 3.8); bx(ba[[m]], 4.8, kcol(k)); linepts(ba[[m]], ba$line, 4.8, lab = TRUE, yl = yl)
  xlab2(c(1, 2, 3.8, 4.8), c("other\nKOs", k, "other\nKOs", k)); mtext(c("CROP-seq screen", "bulk"), side = 1, at = c(1.5, 4.3), line = 3.2, cex = CX * 0.7, font = 2, col = INK2); brk(1, 2, yl, sprintf("FDR %s", fp(sfdr[m, k])), sfdr[m, k] < 0.05); brk(3.8, 4.8, yl, sprintf("p = %s", fp(pb)), !is.na(pb) && pb < 0.05)
  ttl(sprintf("%s  %s in %s KO", letter, m, k), sprintf("screen: %s by %.2f (%s cells)", if (ds < 0) "lower" else "higher", abs(ds), format(length(a), big.mark = ",")), sprintf("bulk: %s by %.2f; same direction in %d of %d lines", if (mean(ba[[m]]) < mean(bo[[m]])) "lower" else "higher", abs(mean(ba[[m]]) - mean(bo[[m]])), sum(sign(pl) == sign(ds), na.rm = TRUE), nrow(ba)), kcol(k)) }
p_rep <- function() { set.seed(5); par(mai = c(0.65, 0.66, 0.85, 0.1), mgp = c(2.3, 0.6, 0), tcl = -0.3); k <- length(LN); sm <- lapply(LN, function(cl) P13$r[P13$line == cl & P13$same]); dv <- lapply(LN, function(cl) P13$r[P13$line == cl & !P13$same]); a <- seq_len(k) * 3 - 1; b <- a + 1; yl <- range(P13$r) + c(-0.03, 0.3)
  plot(NA, xlim = c(0.3, 3 * k + 0.7), ylim = yl, xaxt = "n", bty = "n", las = 1, xlab = "", ylab = "Spearman r between KO samples", cex.axis = 0.8, cex.lab = 0.85); abline(h = 0, col = GRID); boxplot(dv, at = b, add = TRUE, axes = FALSE, outline = FALSE, boxwex = 0.85, col = adjustcolor(GREY, 0.9), border = INK2, lwd = 0.8); boxplot(sm, at = a, add = TRUE, axes = FALSE, outline = FALSE, boxwex = 0.85, col = adjustcolor(LC, 0.85), border = INK2, lwd = 0.8)
  for (i in seq_len(k)) { points(b[i] + runif(length(dv[[i]]), -0.25, 0.25), dv[[i]], pch = 16, col = adjustcolor(INK2, 0.3), cex = 0.35); points(a[i] + runif(length(sm[[i]]), -0.22, 0.22), sm[[i]], pch = 21, bg = LC[i], col = INK, cex = 0.7, lwd = 0.4) }
  axis(1, at = (a + b) / 2, labels = SH(LN), tick = FALSE, cex.axis = 0.85, font = 2, line = -0.6); text((a + b) / 2, yl[2], sprintf("AUC %.2f", S13$AUC), cex = 0.72, col = INK2); text((a + b) / 2, yl[2] - diff(yl) * 0.07, stars(S13$p), cex = 0.85, font = 2)
  ttl("A  KO replicates within each cell line", sprintf("%d KO samples; expressed genes (n = %s), line-centred", sum(SA$KO != "NTC"), paste(format(range(S13$n_genes), big.mark = ","), collapse = "-")), "colour = same-KO pairs, grey = different-KO pairs") }
CROP_PAL <- rev(as.character(paletteer::paletteer_c("ggthemes::Orange-Blue-White Diverging", 100)))
p_ring <- function() { n <- length(GR); m <- length(KOS); vm <- max(abs(unlist(KL)), na.rm = TRUE); RAD <- seq(0.47, 0.17, length.out = length(LN)); cf <- function(v) if (is.na(v)) "grey85" else CROP_PAL[max(1, min(100, round((v + vm) / (2 * vm) * 99) + 1))]; circ <- function(x, y, r, col) { a <- seq(0, 2 * pi, length.out = 48); polygon(x + r * cos(a), y + r * sin(a), col = col, border = NA, xpd = NA) }
  par(mai = c(0.55, 0.72, 0.85, 0.72)); plot(NA, xlim = c(0.5, m + 0.5), ylim = c(0.5, n + 0.5), asp = 1, axes = FALSE, xlab = "", ylab = "", xaxs = "i", yaxs = "i"); for (i in seq_len(n)) for (j in seq_len(m)) for (li in seq_along(LN)) circ(j, n - i + 1, RAD[li], cf(KL[[LN[li]]][GR[i], KOS[j]]))
  for (k in KOS) { i <- match(k, GR); j <- match(k, KOS); rect(j - 0.5, n - i + 0.5, j + 0.5, n - i + 1.5, border = "black", lwd = 0.8) }; abline(h = n - 0.5, col = "grey60", lwd = 0.5); text(seq_len(m), 0.3, KOS, srt = 45, adj = 1, xpd = NA, cex = 0.7, font = 2, col = KO_COL[KOS]); text(0.35, n:1, GR, adj = 1, xpd = NA, cex = 0.7, font = 2, col = c("grey40", KO_COL[KOS]))
  x0 <- m + 0.75; ys <- seq(n * 0.5, n * 0.92, length.out = 101); rect(x0, ys[-101], x0 + 0.3, ys[-1], col = CROP_PAL, border = NA, xpd = NA); text(x0 + 0.4, c(ys[1], ys[51], ys[101]), sprintf("%.1f", c(-vm, 0, vm)), adj = 0, cex = 0.62, xpd = NA, col = INK2); text(x0, ys[101] + 0.35, "row z", adj = 0, cex = 0.62, xpd = NA, col = INK2)
  text(m + 0.75, n * 0.36, paste0("rings, out -> in:\n", paste(SH(LN), collapse = "\n")), adj = c(0, 1), cex = 0.62, xpd = NA, col = INK2); mtext("B  KO target gene expression per line", side = 3, adj = 0, line = 2.9, font = 2, cex = 0.78); mtext(sprintf("boxed = own target; most reduced in %d of %d KO x line", sum(RK == 1, na.rm = TRUE), sum(!is.na(RK))), side = 3, adj = 0, line = 1.75, cex = 0.59, col = INK2) }
foot <- function(tx, h) { par(fig = c(0, 1, 0, h), new = TRUE, mai = c(0, 0.1, 0, 0.1)); plot(NA, xlim = c(0, 1), ylim = c(0, 1), axes = FALSE, xlab = "", ylab = "", xaxs = "i", yaxs = "i"); text(0.003, 0.97 - (0.97 / length(tx)) * (seq_along(tx) - 1), tx, adj = c(0, 1), cex = 0.72, col = INK2, xpd = NA) }
COH <- sprintf(paste0(NLAB, " (genes passing filterByExpr in every line, n = %s), MSTO, H2452, H28; %d NTC + %d KO samples of TEAD4, TWIST1, PITX1, SOX9, TEAD2, BPTF; every step computed on these samples only."), format(length(keep), big.mark = ","), sum(SA$KO == "NTC"), sum(SA$KO != "NTC"))
TXD <- sprintf("D  Cell cycle regressed out (bulk: over the samples of each line; screen: over the NTC + KO cells); each KO vs the mean of the 6 KOs; Spearman over %d genes (top %d variable in screen and bulk); profiles averaged over lines; one-sided Wilcoxon rank-sum (permutation p %s).", length(f), TOPN, fp(pDperm))
TXE <- sprintf("E-G  Top-50 module genes, AddModuleScore, cell cycle regressed; bulk: z within each line over the KO samples, replicates averaged; screen: z over the NTC + KO cells (violins: cell density, white point = median, bar = IQR). Two-sided Wilcoxon; screen FDR over %d module x KO pairs.", length(CM) * length(KOS))

