W <- 15.3; H <- 11.3; HR <- 4.5; R1 <- H - HR - 0.1; R2 <- 1.75; PF <- function(x0, y0, w, h) par(fig = c(x0 / W, (x0 + w) / W, y0 / H, (y0 + h) / H), new = TRUE)
page_cm <- function(off) for (i in seq_along(PAIRS)) { par(cex = 0.66); PF(0.05 + (i - 1) * (wC + 1.05), R2, wC, HP); p_cm(PAIRS[[i]], LETTERS[off + i]) }
